#include "sd_popup.h"
#include <string.h>

/* Exact match without reading more of text than want needs (want's own
 * length + its NUL), so a text with no NUL cannot be overrun. */
static bool text_is(const char *text, const char *want)
{
    return (text != NULL) && (strncmp(text, want, strlen(want) + 1U) == 0);
}

/* -----------------------------------------------------------------------
 * sdp_start_of
 * The starts emit_commands() in tony_ui.c sends: IDLE, PLAYING or PAUSED
 * into RECORDING is a RECORD_START (after a PLAY_STOP), IDLE into PLAYING
 * a PLAY_START. PAUSED into PLAYING is a resume.
 * ----------------------------------------------------------------------- */
sdp_start_t sdp_start_of(const ui_state_t *before, const ui_state_t *after)
{
    if (before == NULL || after == NULL) {
        return SDP_START_NONE;
    }
    if (after->playback == PLAYBACK_RECORDING && before->playback != PLAYBACK_RECORDING) {
        return SDP_START_RECORD;
    }
    if (after->playback == PLAYBACK_PLAYING && before->playback == PLAYBACK_IDLE) {
        return SDP_START_PLAY;
    }
    return SDP_START_NONE;
}

/* -----------------------------------------------------------------------
 * sdp_precheck / sdp_refusal_reason
 * ----------------------------------------------------------------------- */
sdp_reason_t sdp_precheck(bool record, const sv_sd_in_t *sd, uint16_t file_count)
{
    if (sd == NULL || !sd->have_status) {
        return SDP_OK;                  /* nothing known yet: Jack decides */
    }
    if (sd->msc_mode) {
        return SDP_ON_PC;
    }
    if (sd->recording || sd->playing != SV_PLAYING_IDLE || sd->fx_busy) {
        return SDP_OK;                  /* the card is in use, so it is there */
    }
    if (!sd->card_present) {
        return SDP_NO_CARD;
    }
    if (sd->mounted) {
        /* REC makes the first recording; PLAY needs one */
        return (!record && file_count == 0U) ? SDP_NO_FILES : SDP_OK;
    }
    if (text_is(sd->status_text, "Card Full")) {
        return SDP_FULL;
    }
    if (text_is(sd->status_text, "Card Not Ready")) {
        return SDP_NOT_READY;           /* in the slot, not mounted yet */
    }
    return SDP_CARD_ERROR;
}

sdp_reason_t sdp_refusal_reason(bool record, const sv_sd_in_t *sd, uint16_t file_count)
{
    sdp_reason_t why = sdp_precheck(record, sd, file_count);
    return (why == SDP_OK) ? SDP_FAILED : why;
}

/* -----------------------------------------------------------------------
 * sdp_line
 * One row per reason (sdp_reason_t order), its words for REC and for
 * PLAY. Only the lines that name the command differ.
 * ----------------------------------------------------------------------- */
typedef struct {
    const char *rec[SDP_LINES];         /* REC did nothing  */
    const char *play[SDP_LINES];        /* PLAY did nothing */
} sdp_words_t;

static const sdp_words_t s_words[SDP_REASON_COUNT] = {
    [SDP_OK]         = { { "", "", "" },
                         { "", "", "" } },
    [SDP_ON_PC]      = { { "SD CARD ON PC", "Unplug the USB", "to record" },
                         { "SD CARD ON PC", "Unplug the USB", "to play" } },
    [SDP_NO_CARD]    = { { "NO SD CARD", "Insert a card", "to record" },
                         { "NO SD CARD", "Insert a card", "to play" } },
    [SDP_NO_FILES]   = { { "NO RECORDINGS", "Press REC to", "record one" },
                         { "NO RECORDINGS", "Press REC to", "record one" } },
    [SDP_FULL]       = { { "SD CARD FULL", "Free some space", "on a PC" },
                         { "SD CARD FULL", "Free some space", "on a PC" } },
    [SDP_NOT_READY]  = { { "SD NOT READY", "Wait a moment", "and try again" },
                         { "SD NOT READY", "Wait a moment", "and try again" } },
    [SDP_CARD_ERROR] = { { "SD CARD ERROR", "Re-insert it, or", "format as FAT32" },
                         { "SD CARD ERROR", "Re-insert it, or", "format as FAT32" } },
    [SDP_FAILED]     = { { "COULD NOT RECORD", "Please try again", "" },
                         { "COULD NOT PLAY", "Please try again", "" } },
};

const char *sdp_line(sdp_reason_t reason, bool record, uint8_t line)
{
    if ((unsigned)reason >= (unsigned)SDP_REASON_COUNT || line >= SDP_LINES) {
        return "";
    }
    return record ? s_words[reason].rec[line] : s_words[reason].play[line];
}

/* -----------------------------------------------------------------------
 * Showing and closing
 * ----------------------------------------------------------------------- */
void sdp_init(sd_popup_t *p)
{
    if (p == NULL) {
        return;
    }
    memset(p, 0, sizeof(*p));
    p->reason = SDP_OK;
    p->screen = UI_SCREEN_HOME;
}

bool sdp_open(sd_popup_t *p, sdp_reason_t reason, bool record,
              ui_screen_t screen, uint32_t now_ms)
{
    if (p == NULL || reason == SDP_OK || (unsigned)reason >= (unsigned)SDP_REASON_COUNT ||
        (unsigned)screen >= (unsigned)UI_SCREEN_COUNT ||
        screen == UI_SCREEN_FAULT || screen == UI_SCREEN_DEBUG) {
        return false;
    }
    p->open     = true;
    p->record   = record;
    p->reason   = reason;
    p->screen   = screen;
    p->until_ms = now_ms + SDP_SHOW_MS;
    return true;
}

/* Put back first, then open over the screen it is back on: sdp_update()
 * closes a pop-up whose screen is not the one showing. */
bool sdp_refuse(sd_popup_t *p, sdp_reason_t why, bool record, ui_state_t *s,
                ui_screen_t screen, playback_state_t playback, uint32_t now_ms)
{
    if (s == NULL || why == SDP_OK || (unsigned)why >= (unsigned)SDP_REASON_COUNT) {
        return false;
    }
    s->screen   = screen;
    s->playback = playback;
    return sdp_open(p, why, record, s->screen, now_ms);
}

bool sdp_close_on_input(sd_popup_t *p)
{
    if (p == NULL || !p->open) {
        return false;
    }
    p->open = false;
    return true;
}

bool sdp_tap_on_box(sd_popup_t *p, uint16_t x, uint16_t y)
{
    if (p == NULL || !p->open ||
        x < SDP_BOX_X || x >= SDP_BOX_X + SDP_BOX_W || y < SDP_BOX_Y || y >= SDP_BOX_Y + SDP_BOX_H) {
        return false;
    }
    p->open = false;
    return true;
}

/* The same wrap-safe test as the footer notice (sv_notice_active). */
bool sdp_update(sd_popup_t *p, ui_screen_t screen, uint32_t now_ms)
{
    if (p == NULL || !p->open) {
        return false;
    }
    if (screen != p->screen || !sv_notice_active(now_ms, p->until_ms)) {
        p->open = false;
        return true;
    }
    return false;
}
